#include <map>
#include <sstream>
#include <string>
#include <vector>

struct IniResult
{
    std::map<std::string, std::string> values;
    std::vector<std::string> errors;
};

static std::string trim(const std::string& s)
{
    const auto first{ s.find_first_not_of(" \t") };
    if (first == std::string::npos) return "";
    const auto last{ s.find_last_not_of(" \t") };
    return s.substr(first, last - first + 1);
}

IniResult parseIni(const std::string& text)
{
    IniResult result;
    std::string section;
    std::istringstream in{ text };
    std::string raw;
    int number{ 0 };
    while (std::getline(in, raw))
    {
        ++number;
        if (!raw.empty() && raw.back() == '\r') raw.pop_back();
        const std::string line{ trim(raw) };
        if (line.empty() || line[0] == ';' || line[0] == '#') continue;
        if (line.front() == '[')
        {
            if (line.back() != ']' || line.size() < 2) { result.errors.push_back("line " + std::to_string(number) + ": a section needs a closing ]"); continue; }
            section = trim(line.substr(1, line.size() - 2));
            continue;
        }
        const auto equals{ line.find('=') };
        if (equals == std::string::npos) { result.errors.push_back("line " + std::to_string(number) + ": expected key = value"); continue; }
        const std::string key{ trim(line.substr(0, equals)) };
        if (key.empty()) { result.errors.push_back("line " + std::to_string(number) + ": the key is empty"); continue; }
        result.values[section + "." + key] = trim(line.substr(equals + 1));
    }
    return result;
}

unitTests:
TEST("the example")
{
    const auto r{ parseIni("; enemies
[goblin]
health = 30
name = Goblin = small
") };
    CHECK(r.errors.empty());
    CHECK_EQ(r.values.at("goblin.health"), std::string("30"));
    CHECK_EQ(r.values.at("goblin.name"), std::string("Goblin = small"));
}
TEST("keys before any section") { const auto r{ parseIni("volume=7
") }; CHECK_EQ(r.values.at(".volume"), std::string("7")); }
TEST("several sections") { const auto r{ parseIni("[a]
x=1
[b]
x=2
") }; CHECK_EQ(r.values.at("a.x"), std::string("1")); CHECK_EQ(r.values.at("b.x"), std::string("2")); }
TEST("comments, blanks and Windows line endings") { const auto r{ parseIni("# top

  ; indented comment
[s]
k = v
") }; CHECK(r.errors.empty()); CHECK_EQ(r.values.at("s.k"), std::string("v")); }
TEST("the last value wins") { const auto r{ parseIni("[s]
k=1
k=2
") }; CHECK_EQ(r.values.at("s.k"), std::string("2")); }
TEST("errors are reported with line numbers and parsing carries on")
{
    const auto r{ parseIni("[s]
this is wrong
k=1
[broken
= nokey
") };
    CHECK_EQ(r.errors.size(), std::size_t{ 3 });
    CHECK_EQ(r.errors[0].rfind("line 2:", 0), std::size_t{ 0 });
    CHECK_EQ(r.errors[1].rfind("line 4:", 0), std::size_t{ 0 });
    CHECK_EQ(r.errors[2].rfind("line 5:", 0), std::size_t{ 0 });
    CHECK_EQ(r.values.at("s.k"), std::string("1"));
}
TEST("an empty value is allowed") { const auto r{ parseIni("[s]
k =
") }; CHECK(r.errors.empty()); CHECK_EQ(r.values.at("s.k"), std::string("")); }

